effect.shader:
float gmHash(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }
void main(){
  vec2 uv = acScreenNorm;
  float t = acTime * speed;
  uv.x += sin(uv.y * 90.0 + t) * wobble * mixAmt;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = src.a;
  vec3 c = src.rgb / max(a, 1e-4);
  float rr = texture2DCv(inputImg.texture, uv + vec2(bleed, 0.0)).r / max(texture2DCv(inputImg.texture, uv + vec2(bleed, 0.0)).a, 1e-4);
  float bb = texture2DCv(inputImg.texture, uv - vec2(bleed, 0.0)).b / max(texture2DCv(inputImg.texture, uv - vec2(bleed, 0.0)).a, 1e-4);
  c = mix(c, vec3(rr, c.g, bb), 0.8);
  float n = gmHash(floor(uv * acScreenSize) + floor(t * 60.0));
  c += (n - 0.5) * noise * 0.4;
  gl_FragColor = vec4(clamp(c, 0.0, 1.0) * a, a);
}
